def is_prime(n):
    if n == 2 or n == 3:
        return True

    if n < 2 or n % 2 == 0:
        return False

    bitsize = n.bit_length()
    if bitsize >= 1536:
        k = 3
    elif bitsize >= 1024:
        k = 4
    elif bitsize >= 512:
        k = 7
    else:
        k = 10

    # s=log(n)
    s, d = 0, n - 1
    while d % 2 == 0:
        s, d = s + 1, d // 2

    for _ in range(k):
        a = randint(2, n - 2)
        x = pow(a, d, n)

        if x == 1 or x == n - 1:
            continue

        for _ in range(s - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False

    return True


def generate_keys(bits):
    wish = b'Be a good ctfer.'
    seed = int.from_bytes(randbytes(bits // 8), byteorder="little")
    p = (seed + randint(-10e6, 10e6)) | 1
    while not is_prime(p):
        p += 2

    q = (seed + randint(-10e7, 10e7)) | 1
    while not is_prime(q):
        q += 2

    # r = myPrime(bits)
